-- =============================================================================
-- Running: novice-to-pro guides, customisable run plans and run logging.
--   * run_guides / run_guide_catalog – tips by level; bodies of premium guides
--                                      are hidden, titles are listed for all
--   * run_plans                      – the runner's settings; the week-by-week
--                                      plan is generated by @goal4me/core
--   * run_sessions                   – completed runs (feed streaks and badges)
--   * log_run(...)                   – idempotent, offline-safe run logging
--   Free tier (spec: Monetisation): the first 3 runs of every plan and the
--   Starter guides. Enforced here, not only in the app.
-- =============================================================================

alter table public.profiles
  add column runner_level text check (runner_level in ('starter', 'builder', 'racer', 'pro'));

-- -----------------------------------------------------------------------------
-- Guides (content)
-- -----------------------------------------------------------------------------
create table public.run_guides (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9-]+$'),
  level text not null check (level in ('starter', 'builder', 'racer', 'pro')),
  position smallint not null check (position >= 1),
  title text not null,
  body_md text not null,
  try_this text,
  is_premium boolean not null default true,
  is_published boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (level, position)
);

create trigger run_guides_updated_at before update on public.run_guides
  for each row execute function public.set_updated_at();
create trigger run_guides_audit after insert or update or delete on public.run_guides
  for each row execute function public.audit_content_change();

alter table public.run_guides enable row level security;
grant select on public.run_guides to anon, authenticated;
grant insert, update, delete on public.run_guides to authenticated;
create policy "read unlocked guides" on public.run_guides for select to anon, authenticated
  using ((is_published and (not is_premium or (select public.is_premium_user())))
         or (select public.is_admin()));
create policy "admins write" on public.run_guides for all to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));

-- Titles and order of every published guide, so the app can show locked ones.
-- Runs as the view owner, but exposes metadata only (like lesson_catalog).
create view public.run_guide_catalog with (security_invoker = false) as
  select id, slug, level, position, title, is_premium
    from public.run_guides
   where is_published;
grant select on public.run_guide_catalog to anon, authenticated;

-- -----------------------------------------------------------------------------
-- Plans and runs (user-owned)
-- -----------------------------------------------------------------------------
create table public.run_plans (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  program text not null
    check (program in ('couch-to-5k', '5k-to-10k', '5k-speed', '10k-to-half', 'half-to-marathon')),
  -- RunSettings (validated by @goal4me/schemas before it is written).
  settings jsonb not null check (jsonb_typeof(settings) = 'object' and settings ->> 'program' = program),
  intensity numeric(3, 2) not null default 1 check (intensity between 0.85 and 1.15),
  -- Runs completed in order; the app's plan builder turns this into "next run".
  completed_runs smallint not null default 0 check (completed_runs between 0 and 200),
  is_active boolean not null default true,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index run_plans_one_active on public.run_plans (user_id) where is_active;
create trigger run_plans_updated_at before update on public.run_plans
  for each row execute function public.set_updated_at();

create type public.run_effort as enum ('easy', 'just_right', 'hard');

create table public.run_sessions (
  id uuid primary key,  -- generated on the device, so retries never double-count
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  plan_id uuid references public.run_plans (id) on delete set null,
  run_number smallint not null check (run_number between 1 and 200),
  week smallint not null check (week between 1 and 60),
  started_at timestamptz not null,
  duration_s integer not null check (duration_s between 60 and 25200),
  distance_m integer check (distance_m between 0 and 100000),
  effort public.run_effort not null,
  notes text check (char_length(notes) <= 500),
  created_at timestamptz not null default now()
);
create index run_sessions_user_started on public.run_sessions (user_id, started_at desc);
create index run_sessions_plan on public.run_sessions (plan_id);

-- Runs count towards the same streak and badges as workouts.
create trigger run_sessions_after_insert after insert on public.run_sessions
  for each row execute function public.on_workout_logged();

alter table public.run_plans enable row level security;
revoke all on public.run_plans from anon;
grant select, insert, update, delete on public.run_plans to authenticated;
create policy "own rows" on public.run_plans for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- Runs are history: insert (gated) and delete, never edit.
alter table public.run_sessions enable row level security;
revoke all on public.run_sessions from anon;
grant select, insert, delete on public.run_sessions to authenticated;
create policy "read own" on public.run_sessions for select to authenticated
  using (user_id = (select auth.uid()));
create policy "delete own" on public.run_sessions for delete to authenticated
  using (user_id = (select auth.uid()));
create policy "insert own unlocked runs" on public.run_sessions for insert to authenticated
  with check (user_id = (select auth.uid())
              and (run_number <= 3 or (select public.is_premium_user())));

-- -----------------------------------------------------------------------------
-- log_run: records a run and advances the plan in one transaction.
-- Idempotent like log_workout; runs as the caller so RLS gating applies.
-- -----------------------------------------------------------------------------
create function public.log_run(
  p_session_id uuid,
  p_plan_id uuid,
  p_run_number integer,
  p_week integer,
  p_started_at timestamptz,
  p_duration_s integer,
  p_distance_m integer,
  p_effort public.run_effort,
  p_notes text,
  p_next_intensity numeric
) returns boolean
language plpgsql
security invoker
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_started_at > now() + interval '5 minutes' then
    raise exception 'run cannot start in the future' using errcode = '22023';
  end if;
  if p_run_number > 3 and not public.is_premium_user() then
    raise exception 'premium required' using errcode = '42501';
  end if;
  if not exists (select 1 from public.run_plans where id = p_plan_id) then
    raise exception 'run plan not found' using errcode = '22023';  -- RLS: never someone else's
  end if;

  insert into public.run_sessions (id, user_id, plan_id, run_number, week, started_at, duration_s,
                                   distance_m, effort, notes)
  values (p_session_id, uid, p_plan_id, p_run_number, p_week, p_started_at, p_duration_s,
          p_distance_m, p_effort, nullif(btrim(p_notes), ''))
  on conflict (id) do nothing;

  if not found then
    return false;  -- already logged earlier
  end if;

  update public.run_plans
     set completed_runs = greatest(completed_runs, p_run_number),
         intensity = least(1.15, greatest(0.85, coalesce(p_next_intensity, intensity)))
   where id = p_plan_id;

  return true;
end;
$$;

revoke execute on function public.log_run from public, anon;
grant execute on function public.log_run to authenticated;

-- -----------------------------------------------------------------------------
-- Data export now includes running data (same function, two more tables).
-- -----------------------------------------------------------------------------
create or replace function public.export_my_data() returns jsonb
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
  result jsonb := jsonb_build_object('format', 'goal4me-export-v1', 'exported_at', now(), 'user_id', uid);
  t text;
  rows jsonb;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  foreach t in array array['profiles', 'goals', 'body_metrics', 'progress_photos', 'user_programs',
                           'workout_sessions', 'daily_logs', 'streaks', 'achievements', 'budgets',
                           'budget_categories', 'transactions', 'savings_goals',
                           'savings_contributions', 'lesson_progress', 'entitlements',
                           'paynow_payments', 'run_plans', 'run_sessions']
  loop
    execute format(
      'select coalesce(jsonb_agg(to_jsonb(r) - ''user_id''), ''[]''::jsonb) from public.%I r where r.user_id = $1', t)
      into rows using uid;
    result := result || jsonb_build_object(t, rows);
  end loop;
  return result;
end;
$$;
